import React, { useState } from 'react';
import './MenuForms.css';

const MenuForms = () => {
    const [activeBox, setActiveBox] = useState(null);

    const handleBoxClick = (boxName) => {
        setActiveBox(activeBox === boxName ? null : boxName); // Alterna la visibilidad
    };

    return (
        <div className="menu-form">
            <h2>Menu</h2>
            <div className="menu-options">
                <div
                    className={`saving-box ${activeBox === 'ahorro' ? 'active' : ''}`}
                    onClick={() => handleBoxClick('ahorro')}
                >
                    <div className="icon">💰</div>
                    Generar Ahorro
                </div>
                {/* Otros recuadros aquí */}
            </div>
            <div className="menu-container">
                <div className={`info-section ${activeBox === 'ahorro' ? 'active' : ''}`}>
                    <h3>Información sobre Generar Ahorro</h3>
                    <p>Aquí está la información detallada sobre cómo generar ahorro.</p>
                </div>
                {/* Otras secciones de información aquí */}
            </div>
        </div>
    );
};

export default MenuForms;
